  {const x=rig(),marker=join(x.registry.root,"expired-spawn"),old=new Date(Date.now()-2_000).toISOString(),a=x.registry.admit("s",{type:"monitor",mode:"stream",command:`touch '${marker}'`,cwd:process.cwd(),owner_session_id:"s",max_output_bytes:1024,started_at:old,deadline_at:new Date(Date.now()-1_000).toISOString()}).record,restarted=new TaskEngine(x.registry,{runtimeId:"expired-preclaim",tickMs:20,renderClock:testClock(20)});restarted.rehydrate("s",()=>x.dispatcher);await until(()=>x.registry.get(a.task_id)?.status==="timed_out",1_000);assert.equal(existsSync(marker),false);assert.equal(x.registry.get(a.task_id)?.stop_reason,"timeout");assert.equal(x.registry.get(a.task_id)?.lease_token,undefined);}
