test("redirected same-group descendant delays natural completion until group death",async()=>{if(process.platform==="win32")return;const x=rig(),marker=join(x.registry.root,"redirected-late-marker"),r=x.engine.startBash({command:`(sleep .4; touch '${marker}') >/dev/null 2>&1 & exit 0`,cwd:process.cwd(),timeout_s:30,owner_session_id:"s"},x.dispatcher);await wait(150);assert.equal(existsSync(marker),false);assert.equal(x.registry.get(r.task_id)?.ended_at,undefined);await until(()=>existsSync(marker),1_000);await until(()=>x.registry.get(r.task_id)?.status==="completed",1_000);});
test("inherited-stdio same-group descendant delays natural completion until group death",async()=>{if(process.platform==="win32")return;const x=rig(),marker=join(x.registry.root,"inherited-late-marker"),r=x.engine.startBash({command:`(sleep .4; touch '${marker}') & exit 0`,cwd:process.cwd(),timeout_s:30,owner_session_id:"s"},x.dispatcher);await wait(150);assert.equal(existsSync(marker),false);assert.equal(x.registry.get(r.task_id)?.ended_at,undefined);await until(()=>existsSync(marker),1_000);await until(()=>x.registry.get(r.task_id)?.status==="completed",1_000);assert.equal(x.registry.get(r.task_id)?.stdio_drain_timed_out,undefined);});
test("leader exit is bounded when a detached grandchild retains stdio",async()=>{if(process.platform==="win32")return;const x=rig();x.engine=new TaskEngine(x.registry,{tickMs:20,renderClock:testClock(20),stdioDrainTimeoutMs:50});const r=x.engine.startBash({command:"setsid sh -c 'sleep 2' & exit 0",cwd:process.cwd(),timeout_s:30,owner_session_id:"s"},x.dispatcher);await until(()=>Boolean(x.registry.get(r.task_id)?.ended_at),1_000);assert.equal(x.registry.get(r.task_id)?.status,"completed");assert.equal(x.registry.get(r.task_id)?.stdio_drain_timed_out,true);});

test("nonzero exits preserve output and dispatch exit 7 once for bash and stream",async()=>{for(const kind of ["bash","stream"] as const){const x=rig(),r=kind==="bash"?x.engine.startBash({command:"printf 'before-exit-7\\n'; exit 7",cwd:process.cwd(),timeout_s:30,owner_session_id:"s"},x.dispatcher):x.engine.startMonitor({command:"printf 'before-exit-7\\n'; exit 7",cwd:process.cwd(),throttle_s:10,owner_session_id:"s"},x.dispatcher);await until(()=>x.registry.get(r.task_id)?.status==="failed");await until(()=>x.registry.get(r.task_id)?.dispatch_state==="host_api_invoked");const current=x.registry.get(r.task_id)!;assert.match(readFileSync(r.output_path,"utf8"),/before-exit-7/);assert.equal(current.exit_code,7);assert.equal(current.pid,undefined);assert.equal(current.pgid,undefined);assert.equal(current.owner_runtime_id,undefined);assert.equal(current.lease_token,undefined);const notifications=x.sent.map(v=>v.content).join("\n");assert.equal((notifications.match(/<status>failed<\/status>/g)??[]).length,1);assert.equal((notifications.match(/<exit_code>7<\/exit_code>/g)??[]).length,1);}});

test("interval stdout budget overflow fails with sentinel",async()=>{const x=rig();const r=x.engine.startMonitor({command:"head -c 5242881 /dev/zero",cwd:process.cwd(),interval_s:5,until_output_matches:"never",throttle_s:0,owner_session_id:"s"},x.dispatcher);await until(()=>Boolean(x.registry.get(r.task_id)?.ended_at),5_000);assert.equal(x.registry.get(r.task_id)?.status,"failed");assert.match(readFileSync(r.output_path,"utf8"),/exceeded 5242880-byte budget/);});
test("real bash engine stops at 10MiB and retains exactly the first cap plus sentinel",async()=>{const x=rig(),command=`node -e 'process.stdout.write(Buffer.alloc(${BASH_OUTPUT_CAP+1024},65)); setTimeout(()=>{},10000)'`,r=x.engine.startBash({command,cwd:process.cwd(),timeout_s:30,owner_session_id:"s"},x.dispatcher);await until(()=>x.registry.get(r.task_id)?.status==="stopped",8_000);const output=readFileSync(r.output_path);assert.equal(x.registry.get(r.task_id)?.stop_reason,"output_cap");assert.equal(output.subarray(0,BASH_OUTPUT_CAP).equals(Buffer.alloc(BASH_OUTPUT_CAP,65)),true);assert.match(output.subarray(BASH_OUTPUT_CAP).toString(),/output cap reached at 10485760 payload bytes; process stopped/);});
test("real stream monitor rolls beyond 5MiB, keeps newest sentinel, and completes naturally",async()=>{const x=rig(),marker="NEWEST-MONITOR-SENTINEL",command=`node -e 'process.stdout.write(Buffer.alloc(${MONITOR_OUTPUT_CAP+1024},65)); process.stdout.write("${marker}\\n")'`,r=x.engine.startMonitor({command,cwd:process.cwd(),throttle_s:0,owner_session_id:"s"},x.dispatcher);await until(()=>x.registry.get(r.task_id)?.status==="completed",8_000);const output=readFileSync(r.output_path);assert.match(output.toString(),/older output truncated/);assert.match(output.toString(),new RegExp(marker));const mark=output.toString().match(/^\n?\[task-plane monitor\].*\n/)?.[0]??"";assert.ok(output.length<=MONITOR_OUTPUT_CAP+Buffer.byteLength(mark));});

test("engine runtime ownership is per instance",()=>{const registry=new TaskRegistry(mkdtempSync(join(tmpdir(),"runtime-owner-")));const a=new TaskEngine(registry),b=new TaskEngine(registry);assert.notEqual(a.runtimeId,b.runtimeId);});
